std::shared_mutex mtx;
std::unordered_map<std::string, std::shared_ptr<const Page>> pages;

std::shared_ptr<const Page> lookup(std::string const& key) {
    std::shared_lock read(mtx);              // hits do not block each other
    auto it = pages.find(key);
    if (it == pages.end() || it->second->expired()) return {};
    return it->second;                       // keeps the bytes alive past unlock
}
